"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type BeforeAfterSliderPrimitiveProps = ComponentProps<typeof motion.div>;

export function BeforeAfterSliderPrimitive({ children, ...props }: BeforeAfterSliderPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      drag="x"
      dragConstraints={{ left: 0, right: 0 }}
      dragElastic={0.18}
      whileDrag={reduceMotion ? undefined : {scale: 1.015}}
      transition={reduceMotion ? { duration: 0.12 } : { type: "spring", stiffness: 360, damping: 30 }}
    >
      {children}
    </motion.div>
  );
}
